        v._r[1] = reg_t::min(_r[1], b._r[1]);
        v._r[2] = reg_t::min(_r[2], b._r[2]);
        v._r[3] = reg_t::min(_r[3], b._r[3]);
        v._r[4] = reg_t::min(_r[4], b._r[4]);
        v._r[5] = reg_t::min(_r[5], b._r[5]);
        v._r[6] = reg_t::min(_r[6], b._r[6]);
        v._r[7] = reg_t::min(_r[7], b._r[7]);
