        v._r[1] = reg_t::sqrt(_r[1]);
        v._r[2] = reg_t::sqrt(_r[2]);
        v._r[3] = reg_t::sqrt(_r[3]);
        v._r[4] = reg_t::sqrt(_r[4]);
        v._r[5] = reg_t::sqrt(_r[5]);
        v._r[6] = reg_t::sqrt(_r[6]);
