        v._r[2] = reg_t::floor(_r[2]);
        v._r[3] = reg_t::floor(_r[3]);
        v._r[4] = reg_t::floor(_r[4]);
        v._r[5] = reg_t::floor(_r[5]);
        v._r[6] = reg_t::floor(_r[6]);
        v._r[7] = reg_t::floor(_r[7]);
